//! Responses generated by RXH itself.

use hyper::Response;
use hyper::StatusCode;
use hyper::header;

use crate::http::body::{self, Body};

/// Response type of the HTTP service.
pub(crate) type BoxResponse = Response<Body>;

/// Value of the `Server` header.
pub(crate) fn server_header(with_version: bool) -> String {
    if with_version {
        format!("rxh/{}", crate::VERSION)
    } else {
        String::from("rxh")
    }
}

/// Builder with the `Server` header already set.
pub(crate) fn builder() -> http::response::Builder {
    Response::builder().header(header::SERVER, server_header(true))
}

/// Plain text response with the given status.
pub(crate) fn plain(status: StatusCode, text: &'static str) -> BoxResponse {
    let mut response = Response::new(body::full(text));
    *response.status_mut() = status;
    let headers = response.headers_mut();
    headers.insert(
        header::SERVER,
        server_header(true).parse().expect("valid header value"),
    );
    headers.insert(
        header::CONTENT_TYPE,
        header::HeaderValue::from_static("text/plain"),
    );
    response
}

/// Redirect to `location` with an empty body. `400` if `location` is not a
/// valid header value, which only a hostile `Host` can cause.
pub(crate) fn redirect(status: StatusCode, location: &str) -> BoxResponse {
    let Ok(location) = header::HeaderValue::from_str(location) else {
        return plain(StatusCode::BAD_REQUEST, "HTTP 400 BAD REQUEST");
    };
    let mut response = plain(status, "");
    response.headers_mut().insert(header::LOCATION, location);
    response
}

/// `404 Not Found`.
pub(crate) fn not_found() -> BoxResponse {
    plain(StatusCode::NOT_FOUND, "HTTP 404 NOT FOUND")
}

/// `413 Content Too Large`: the request body is over `request.max_body_size`.
pub(crate) fn payload_too_large() -> BoxResponse {
    plain(StatusCode::PAYLOAD_TOO_LARGE, "HTTP 413 CONTENT TOO LARGE")
}

/// `502 Bad Gateway`: the backend failed.
pub(crate) fn bad_gateway() -> BoxResponse {
    plain(StatusCode::BAD_GATEWAY, "HTTP 502 BAD GATEWAY")
}

/// `503 Service Unavailable`: no backend is available.
pub(crate) fn service_unavailable() -> BoxResponse {
    plain(
        StatusCode::SERVICE_UNAVAILABLE,
        "HTTP 503 SERVICE UNAVAILABLE: no upstreams available",
    )
}

/// `504 Gateway Timeout`: the backend did not answer in time.
pub(crate) fn gateway_timeout() -> BoxResponse {
    plain(StatusCode::GATEWAY_TIMEOUT, "HTTP 504 GATEWAY TIMEOUT")
}
